	this.butt = new lib.buttonnormal();
	this.butt.parent = this;
	this.butt.setTransform(47.4,62,0.657,1.169,0,178.2,179.2,57.5,68.7);
	this.butt.alpha = 0;
	new cjs.ButtonHelper(this.butt, 0, 1, 2, false, new lib.buttonnormal(), 3);

	this.timeline.addTween(cjs.Tween.get(this.butt).to({_off:true},1).wait(87));

	// Layer 1
	this.instance = new lib.monkall();
	this.instance.parent = this;
	this.instance.setTransform(40.3,66.7,0.581,0.581,0,0,0,69.2,114.6);

