	this.instance_2.parent = this;
	this.instance_2.setTransform(40.3,66.7,0.581,0.581,0,0,0,69.2,114.6);
	this.instance_2._off = true;

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance}]}).to({state:[{t:this.instance_1}]},1).to({state:[{t:this.instance_2}]},1).to({state:[{t:this.instance_2}]},52).to({state:[]},1).wait(33));
